import {json} from "../../_lib/auth.js";
import {getChatUser} from "../../_lib/chat-session.js";
const encoder=new TextEncoder();
function equal(a,b){const x=encoder.encode(a),y=encoder.encode(b);let diff=x.length^y.length;for(let i=0;i<Math.max(x.length,y.length);i++)diff|=(x[i]||0)^(y[i]||0);return diff===0;}
async function ipHash(request){const value=request.headers.get("CF-Connecting-IP")||"unknown";const digest=await crypto.subtle.digest("SHA-256",encoder.encode(value));return Array.from(new Uint8Array(digest),b=>b.toString(16).padStart(2,"0")).join("");}
export async function onRequestGet({request,env}){const user=await getChatUser(request,env);if(!user)return json({setupAvailable:false,isAdmin:false});const admin=Number(user.is_admin)===1;const existing=await env.DB.prepare("SELECT id FROM chat_users WHERE is_admin=1 LIMIT 1").first();return json({setupAvailable:!existing&&Boolean(env.ADMIN_PASSWORD),isAdmin:admin});}
export async function onRequestPost({request,env}){const user=await getChatUser(request,env);if(!user)return json({error:"Log in to your chat account first."},401);if(!env.ADMIN_PASSWORD)return json({error:"Admin setup secret is not configured."},503);if(Number(user.is_admin)===1)return json({ok:true,isAdmin:true});const existing=await env.DB.prepare("SELECT id FROM chat_users WHERE is_admin=1 LIMIT 1").first();if(existing)return json({error:"An admin account has already been set up."},409);const ip=await ipHash(request);const attempt=await env.DB.prepare("SELECT failures,window_start,blocked_until,(blocked_until>datetime('now')) AS blocked FROM admin_login_attempts WHERE ip_hash=?").bind(ip).first();if(attempt?.blocked)return json({error:"Too many setup attempts. Try again in 15 minutes."},429);const body=await request.json().catch(()=>({}));const supplied=typeof body.password==="string"?body.password:"";if(supplied.length>256||!equal(supplied,env.ADMIN_PASSWORD)){const failures=attempt?.window_start&&attempt.window_start>=new Date(Date.now()-900000).toISOString().slice(0,19).replace("T"," ")?attempt.failures+1:1;await env.DB.prepare("INSERT INTO admin_login_attempts(ip_hash,failures,window_start,blocked_until) VALUES(?,?,datetime('now'),CASE WHEN ?>=5 THEN datetime('now','+15 minutes') ELSE NULL END) ON CONFLICT(ip_hash) DO UPDATE SET failures=CASE WHEN admin_login_attempts.window_start<datetime('now','-15 minutes') THEN 1 ELSE admin_login_attempts.failures+1 END,window_start=CASE WHEN admin_login_attempts.window_start<datetime('now','-15 minutes') THEN datetime('now') ELSE admin_login_attempts.window_start END,blocked_until=CASE WHEN (CASE WHEN admin_login_attempts.window_start<datetime('now','-15 minutes') THEN 1 ELSE admin_login_attempts.failures+1 END)>=5 THEN datetime('now','+15 minutes') ELSE NULL END").bind(ip,failures,failures).run();return json({error:"Incorrect admin setup password."},401);}await env.DB.prepare("UPDATE chat_users SET is_admin=1 WHERE id=? AND NOT EXISTS(SELECT 1 FROM chat_users WHERE is_admin=1)").bind(user.id).run();const promoted=await env.DB.prepare("SELECT is_admin FROM chat_users WHERE id=?").bind(user.id).first();if(Number(promoted?.is_admin)!==1)return json({error:"Admin setup has already been claimed by another account."},409);await env.DB.prepare("DELETE FROM admin_login_attempts WHERE ip_hash=?").bind(ip).run();return json({ok:true,isAdmin:true});}
